-- Existing connections retain their original read-only authority.
ALTER TABLE mcp_authorizations ADD COLUMN scope TEXT NOT NULL DEFAULT 'portfolio:read' CHECK(scope IN ('portfolio:read','domains:write','portfolio:read domains:write','domains:spend','portfolio:read domains:spend','domains:write domains:spend','portfolio:read domains:write domains:spend'));
ALTER TABLE mcp_grants ADD COLUMN scope TEXT NOT NULL DEFAULT 'portfolio:read' CHECK(scope IN ('portfolio:read','domains:write','portfolio:read domains:write','domains:spend','portfolio:read domains:spend','domains:write domains:spend','portfolio:read domains:write domains:spend'));
